FlowController.prototype.getCorrectLocale = function (loc) {
    var languageString = loc.replace(/_/, "-");
    switch (languageString) {
        case "en-us":
        case "en-gb":
        case "nl-nl":
        case "fr-fr":
        case "it-it":
        case "de-de":
        case "es-es":
        case "tr-tr":
        case "id-id":
        case "vi-vi":
        case "th-th":
        case "pt-br":
        case "pl-pl":
            break;
        default:
            if (languageString.startsWith("nl-"))
                languageString = "nl-nl";
            else if (languageString.startsWith("fr-"))
                languageString = "fr-fr";
            else if (languageString.startsWith("it-"))
                languageString = "it-it";
            else if (languageString.startsWith("de-"))
                languageString = "de-de";
            else if (languageString.startsWith("es-"))
                languageString = "es-es";
            else if (languageString.startsWith("tr-"))
                languageString = "tr-tr";
            else if (languageString.startsWith("id-"))
                languageString = "id-id";
            else if (languageString.startsWith("in-"))
                languageString = "id-id";
            else if (languageString.startsWith("vi-"))
                languageString = "vi-vi";
            else if (languageString.startsWith("th-"))
                languageString = "th-th";
            else if (languageString.startsWith("pl-"))
                languageString = "pl-pl";
            else if (languageString.startsWith("pt-"))
                languageString = "pt-br";
            else
                languageString = "en-us";
            break;
    }
    return languageString;
};
